const e=$json.body;
const allowed=['DEVICE_CONNECTED','DEVICE_DISCONNECTED','SIGNAL_WEAK','SIGNAL_RECOVERED','COVERAGE_LIMIT_REACHED','MOVEMENT_DETECTED','MOTION_ALERT','SENSOR_OFFLINE','SENSOR_RECOVERED','HEARTBEAT'];
if(!e || !allowed.includes(e.event) || !/^[0-9a-f]{16}$/.test(e.boot_id) || !Number.isInteger(e.sequence) || e.sequence<1 || !Number.isInteger(e.timestamp_ms) || e.timestamp_ms<0 || typeof e.simulated!=='boolean' || typeof e.notify!=='boolean')return [];
if(!Number.isInteger(e.client_id)||e.client_id<0||e.client_id>4294967295||e.sequence>4294967295||e.timestamp_ms>4294967295)return [];
if(e.rssi_dbm!==null && (!Number.isFinite(e.rssi_dbm)||e.rssi_dbm< -100||e.rssi_dbm>=0))return [];
if(e.distance_estimated_m!==null && (!Number.isFinite(e.distance_estimated_m)||e.distance_estimated_m<=0))return [];
const s=$getWorkflowStaticData('global'),now=Date.now();
s.seen=s.seen||[];const id=e.boot_id+':'+e.sequence;if(s.seen.includes(id))return [];s.lastSeen=now;s.offline=false;
if(e.event==='HEARTBEAT'){s.seen.push(id);s.seen=s.seen.slice(-512);return []}
if(!e.notify||e.simulated||!['SIGNAL_WEAK','DEVICE_DISCONNECTED','MOTION_ALERT','SENSOR_OFFLINE'].includes(e.event))return [];
return [{json:{id,message:'SENTINEL RF · '+e.event+'\nCliente '+e.client_id+'\nRSSI: '+(e.rssi_dbm??'no disponible')+' dBm\nESTIMACIÓN POR RSSI: '+(e.distance_estimated_m??'sin calibración')+' m\nTiempo relativo: '+e.timestamp_ms+' ms'}}];

const s=$getWorkflowStaticData('global');
const timeoutMs=60000; // Configurable; must exceed heartbeat + queue/network delay.
if(!s.lastSeen || s.offline || Date.now()-s.lastSeen<=timeoutMs)return [];
return [{json:{id:'offline:'+s.lastSeen,offline:true,message:'SENTINEL RF: no se recibe heartbeat desde hace más de '+timeoutMs/1000+' s. Puede ser pérdida de red, servicio o alimentación; causa no determinada.'}}];
